mapper.select:
SELECT EXPENSE_ID AS expenseId,
       ID AS id,
       CATEGORY_NAME AS categoryName,
       AMOUNT AS amount,
       SPENT_AT AS spentAt
FROM EXPENSE_CATEGORY
WHERE ID = #{ownerId}
  AND SPENT_AT >= #{fromDate}
  AND SPENT_AT < #{untilDate}
ORDER BY SPENT_AT DESC, EXPENSE_ID DESC

SELECT CATEGORY_NAME AS categoryName,
       SUM(AMOUNT) AS totalAmount,
       COUNT(*) AS expenseCount
FROM EXPENSE_CATEGORY
WHERE ID = #{ownerId}
  AND SPENT_AT >= #{fromDate}
  AND SPENT_AT < #{untilDate}
GROUP BY CATEGORY_NAME
ORDER BY SUM(AMOUNT) DESC

mapper.update:
UPDATE EXPENSE_CATEGORY
SET CATEGORY_NAME = #{categoryName},
    AMOUNT = #{amount},
    SPENT_AT = #{spentAt}
WHERE EXPENSE_ID = #{expenseId}
  AND ID = #{id}

mapper.delete:
DELETE FROM EXPENSE_CATEGORY
WHERE EXPENSE_ID = #{expenseId}
  AND ID = #{ownerId}
